@extends('layouts.app') @section('title',$credential->exists?'Editar credencial':'Nueva credencial') @section('content')<form class="panel form" method="POST" action="{{$credential->exists?route('credentials.update',$credential):route('credentials.store')}}">@csrf @if($credential->exists)@method('PUT')@endif<label>Proyecto<select name="project_id"><option value="">General</option>@foreach($projects as $p)<option value="{{$p->id}}" @selected(old('project_id',$credential->project_id ?? request('project_id'))==$p->id)>{{$p->name}}</option>@endforeach</select></label><label>Nombre / acceso<input name="label" value="{{old('label',$credential->label)}}" required></label><label>Usuario<input name="username" value="{{old('username',$plainUser??'')}}" autocomplete="off"></label><label>Contraseña<input id="vault-password" type="password" name="password" {{$credential->exists?'':'required'}} autocomplete="new-password" placeholder="{{$credential->exists?'Dejar vacío para conservar':''}}"><button class="btn ghost" type="button" style="margin-top:7px" onclick="generateVaultPassword()">Generar segura</button></label><label>URL<input name="url" value="{{old('url',$credential->url)}}"></label><label>Categoría<input name="category" value="{{old('category',$credential->category)}}" placeholder="Servidor, BD, Admin..."></label><label class="wide">Notas<textarea name="notes">{{old('notes',$plainNotes??'')}}</textarea></label><button class="btn">Guardar cifrado</button></form><script>function generateVaultPassword(){const el=document.getElementById('vault-password');if(el.value && !confirm('Ya hay una contraseña escrita. ¿Deseas reemplazarla por una nueva contraseña generada?'))return;const chars='ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789!@#$%&*+-_';const a=new Uint32Array(24);crypto.getRandomValues(a);el.value=Array.from(a,x=>chars[x%chars.length]).join('');el.type='text';setTimeout(()=>{el.type='password'},5000);}</script>@endsection
